def backfill_loans(apps, schema_editor):
    """Copy in-flight borrow state from Book rows into Loan rows.

    Historically, borrow state (borrower, borrow date, due date) lived
    directly on the Book row and was overwritten/wiped on return, so this
    only needs to look at books that are *currently* borrowed (user is not
    null) - there is no history to recover for already-returned books,
    because none was ever kept.
    """
    Book = apps.get_model("books", "Book")
    Loan = apps.get_model("loans", "Loan")

    borrowed_books = Book.objects.filter(user__isnull=False)
    created = 0
    for book in borrowed_books:
        borrowed_at = book.borrow_date or book.return_date or None
        if borrowed_at is None:
            # No usable date at all was ever recorded for this borrow;
            # fall back to "today" so the loan is at least created rather
            # than silently dropped.
            from django.utils import timezone

            borrowed_at = timezone.localdate()

        if book.return_date:
            due_at = book.return_date
        else:
            period = book.borrow_period or 14
            due_at = borrowed_at + timedelta(days=period)

        Loan.objects.create(
            book=book,
            borrower=book.user,
            borrowed_at=borrowed_at,
            due_at=due_at,
            returned_at=None,
        )
        created += 1

    if created:
        print(f"\n  Backfilled {created} active loan(s) from existing Book borrow state.")


